            if ($start !== null && str_contains($line, '<<<END-PAYLOAD>>>')) {
                $end = $i;
                break;
            }
        }
        if ($start === null || $end === null) {
            throw new \RuntimeException("payload sentinels not found in {$file}");
        }

        $region = array_slice($lines, $start + 1, $end - $start - 1);

